const {spawn} = require('node:child_process');
const fs = require('node:fs/promises');
const assert = require('node:assert/strict');
const pause = () => new Promise(resolve => setTimeout(resolve, 150));
(async () => {
  const profile = await fs.mkdtemp('/tmp/spatial-chrome-');
  const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', [
    '--headless', '--no-first-run', '--remote-debugging-port=0',
    '--user-data-dir=' + profile, 'about:blank'
  ], {stdio:'ignore'});
  try {
    let port;
    for (let i = 0; i < 100 && !port; i++) {
      try { port = (await fs.readFile(profile + '/DevToolsActivePort', 'utf8')).split('\\n')[0]; }
      catch { await pause(); }
    }
    assert.ok(port);
    const [tab] = await (await fetch('http://127.0.0.1:' + port + '/json/list')).json();
    const ws = new WebSocket(tab.webSocketDebuggerUrl);
    await new Promise((resolve, reject) => {
      ws.addEventListener('open', resolve);
      ws.addEventListener('error', reject);
    });
    let id = 0;
    function send(method, params) {
      const request = ++id;
      return new Promise(resolve => {
        function onMessage(event) {
          const data = JSON.parse(event.data);
          if (data.id !== request) return;
          ws.removeEventListener('message', onMessage);
          resolve(data.result);
        }
        ws.addEventListener('message', onMessage);
        ws.send(JSON.stringify({id: request, method, params}));
      });
    }
    await send('Page.navigate', {url:'http://127.0.0.1:8519'});
    for (let i = 0; i < 120; i++) {
      const {result} = await send('Runtime.evaluate', {
        expression: 'document.body?.innerText || ""', returnByValue:true
      });
      if (['Spatial target evidence', 'Human tissue and reported liabilities',
           'Reviewed compound and intervention evidence', 'Download reviewed compound evidence']
          .every(label => result.value.includes(label))) {
        ws.close();
        console.log('Fresh Chrome profile rendered the ranking, tissue, compound evidence, and download controls.');
        return;
      }
      await pause();
    }
    throw new Error('Streamlit browser rendering did not finish');
  } finally { chrome.kill(); }
})().catch(error => {console.error(error); process.exitCode = 1;});
